 1	import { EventEmitter } from 'node:events';
 2	import type { IncomingMessage, ServerResponse } from 'node:http';
 3	
 4	export function mockRequest(method: string, url: string, bodyJson?: unknown): IncomingMessage {
 5	    const req = new EventEmitter() as IncomingMessage;
 6	    (req as unknown as { method: string }).method = method;
 7	    (req as unknown as { url: string }).url = url;
 8	    (req as unknown as { destroy(): void }).destroy = () => {
 9	        req.emit('error', new Error('destroyed'));
10	    };
11	
12	    process.nextTick(() => {
13	        if (bodyJson !== undefined) {
14	            req.emit('data', Buffer.from(JSON.stringify(bodyJson)));
15	        }
16	        req.emit('end');
17	    });
18	
19	    return req;
20	}
21	
22	export interface MockResponse {
23	    statusCode: number | undefined;
24	    body: string;
25	    res: ServerResponse;
26	}
27	
28	export function mockResponse(): MockResponse {
29	    const mock: MockResponse = {
30	        statusCode: undefined,
31	        body: '',
32	        res: null as unknown as ServerResponse,
33	    };
34	
35	    const res = new EventEmitter() as unknown as ServerResponse;
36	
37	    (res as unknown as {
38	        writeHead(status: number, headers?: Record<string, string | number>): void;
39	    }).writeHead = (status: number) => {
40	        mock.statusCode = status;
41	    };
42	
43	    (res as unknown as { end(body?: string): void }).end = (body?: string) => {
44	        mock.body = body ?? '';
45	    };
46	
47	    mock.res = res;
48	    return mock;
49	}

